// EINZELTEST: single_order = exakter Bestellname (BB-...) oder Shopify-ID.
// MASSEN-VORSCHAU: mode = 'batch'. Kein automatischer Datumsfilter.
// dry_run bleibt true, bis Vorschau und JTL-Zielzahlungsart geprueft sind.
// Zielzahlungsart: ID oder exakten Namen aus dem Zahlungsarten-Katalog eintragen.
// invoice_policy: 'review' = Auftraege mit Rechnung nur melden;
// 'order_only' = nur den Auftrag aendern, bestehende Rechnungen bleiben unveraendert.
// max_changes begrenzt echte Aenderungen; bei Ueberschreitung wird VOR dem Schreiben abgebrochen.
// batch_order_names: optional exakte Bestellnamen aus der Vorschau fuer einen kleinen Live-Stapel.
// Datumsfilter: UTC; created_from inklusive, created_before exklusiv. Leer = alle Jahrgaenge.
// JTL-Datenbank, kShop=3 und Zugang stammen aus euren Vorlagen. Im ersten dry_run pruefen.
const settings = {
  "dry_run": false,
  "mode": "batch",
  "single_order": "",
  "batch_order_names": [],
  "created_from": "",
  "created_before": "",
  "target_payment_id": 12,
  "target_payment_name": "Rechnung",
  "source_payment_names": [
    "shopify_payments"
  ],
  "source_payment_ids": [],
  "invoice_policy": "review",
  "max_changes": 100,
  "shop_domain": "vdzvc0-nd.myshopify.com",
  "api_version": "2026-07",
  "jtl_database": "eazybusiness",
  "jtl_shop_id": 33,
  "tag": "BB Klarna Rechnung",
  "page_size": 100,
  "max_orders": 10000,
  "max_pages": 200,
  "sql_batch_size": 100
};

