  if (!Array.isArray(c.batch_order_names) || !c.batch_order_names.every(n => typeof n === 'string' && n.length > 0 && n.length <= 50))
    fail('batch_order_names muss eine Liste exakter Bestellnamen sein.');
  if (new Set(c.batch_order_names).size !== c.batch_order_names.length) fail('Doppelte Namen in batch_order_names.');
  if (c.mode === 'single' && c.batch_order_names.length) fail('Im Einzelmodus batch_order_names leeren.');
  for (const key of ['created_from', 'created_before']) {
    if (typeof c[key] !== 'string' || (c[key] && (!/^\d{4}-\d{2}-\d{2}$/.test(c[key])
      || !Number.isFinite(Date.parse(c[key])) || new Date(c[key]).toISOString().slice(0, 10) !== c[key])))
      fail(key + ': Datum als YYYY-MM-DD oder leer eingeben.');
  }
  if (c.created_from && c.created_before && c.created_from >= c.created_before) fail('Datumsbereich ist leer.');
  if (c.mode === 'single' && (c.created_from || c.created_before)) fail('Im Einzelmodus Datumsfilter leeren.');
  if (!/^[a-z0-9][a-z0-9-]*\.myshopify\.com$/.test(c.shop_domain)) fail('Ungueltige myshopify.com-Domain.');
  if (!/^\d{4}-(01|04|07|10)$/.test(c.api_version)) fail('Ungueltige Shopify-API-Version.');
  if (typeof c.jtl_database !== 'string' || !c.jtl_database.trim()) fail('JTL-Datenbank fehlt.');
  positive(c.jtl_shop_id, 'jtl_shop_id');
  if (c.tag !== 'BB Klarna Rechnung') fail('Dieser Workflow erwartet das Tag BB Klarna Rechnung.');
  if (!Number.isInteger(c.target_payment_id) || c.target_payment_id < 0 || c.target_payment_id > 2147483647)
    fail('target_payment_id muss 0 oder eine positive JTL-ID sein.');
  if (typeof c.target_payment_name !== 'string') fail('target_payment_name muss Text sein.');
  c.target_payment_name = c.target_payment_name.trim();
  if (!Array.isArray(c.source_payment_names) || !c.source_payment_names.every(n => typeof n === 'string' && n.trim()))
    fail('Ungueltige source_payment_names.');
  if (!Array.isArray(c.source_payment_ids)) fail('source_payment_ids muss eine Liste sein.');
  c.source_payment_ids.forEach(n => positive(n, 'source_payment_ids'));
  if (!['review', 'order_only'].includes(c.invoice_policy)) fail('invoice_policy muss review oder order_only sein.');
  for (const [key, min, max] of [['max_changes', 1, 100], ['page_size', 1, 100], ['max_orders', 1, 20000],
    ['max_pages', 1, 2000], ['sql_batch_size', 1, 200]]) {
    if (!Number.isInteger(c[key]) || c[key] < min || c[key] > max) fail(key + ': erlaubter Bereich ' + min + '..' + max);
  }
  if (!c.dry_run && !c.target_payment_id && !c.target_payment_name) fail('Vor einem Schreiblauf Zielzahlungsart eintragen.');
  c.started_at = new Date().toISOString();
  return one(c);
})(settings);

