      if (!status && locked) status = 'JTL_GESPERRT';
      if (!status && external) status = 'JTL_EXTERNE_RECHNUNG_PRUEFEN';
      if (!status && catalog.target && a.payment_id === catalog.target.id) status = 'BEREITS_KORREKT';
      if (!status && invoiced && c.invoice_policy === 'review') status = 'JTL_RECHNUNG_VORHANDEN_PRUEFEN';
