      financial_status: o.displayFinancialStatus, status,
      jtl_id: a?.jtl_id ?? null, jtl_number: a?.jtl_number ?? '',
      current_payment_id: a?.payment_id ?? null, current_payment_name: a?.payment_name ?? '',
      target_payment_id: catalog.target?.id ?? null, target_payment_name: catalog.target?.name ?? c.target_payment_name,
      has_invoice: a?.has_invoice ?? null,
