return (function verifyLiveShopify() {
  const c = config();
  const plan = $('Aenderungsplan').first().json;
  if (c.dry_run !== false || !plan.can_write) fail('DRY_RUN: Schreibpfad gesperrt.');
  if (!plan.changes.length || plan.changes.length > c.max_changes || plan.changes.length > 100) fail('Aenderungslimit verletzt.');
  const nodes = graphqlData(responseBody($input.first())).nodes;
  if (!Array.isArray(nodes) || nodes.length !== plan.changes.length) fail('Shopify-Rueckpruefung ist unvollstaendig.');
  const fresh = new Map();
  for (const o of nodes) {
    validateOrder(o);
    if (fresh.has(o.id)) fail('Doppelte Bestell-ID in Shopify-Rueckpruefung.');
    fresh.set(o.id, o);
  }
  for (const p of plan.changes) {
    const o = fresh.get(p.shopify_id);
    if (!o || o.name !== p.shopify_name || o.updatedAt !== p.shopify_updated_at || shopifyReason(o, c))
      fail('Shopify-Bestellung hat sich seit der Planung geaendert: ' + p.shopify_name + '. Keine JTL-Aenderung.');
