SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_WARNINGS ON;
SET ANSI_PADDING ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET ARITHABORT ON;
SET NUMERIC_ROUNDABORT OFF;
SET LOCK_TIMEOUT 10000;

DECLARE @dryRun bit = $2, @shop int = $3, @expectedDb nvarchar(128) = $4,
        @invoicePolicy nvarchar(20) = $5, @target int = $6, @maxChanges int = $7;
IF @dryRun IS NULL OR @dryRun <> 0
    THROW 51000, 'DRY_RUN: Schreibzugriff gesperrt.', 1;
IF DB_NAME() <> @expectedDb OR @expectedDb IS NULL
    THROW 51001, 'Unerwartete JTL-Datenbank.', 1;
IF @shop IS NULL OR @shop <= 0 OR @target IS NULL OR @target <= 0
    THROW 51002, 'Shop oder Zielzahlungsart fehlt.', 1;
IF @invoicePolicy IS NULL OR @invoicePolicy NOT IN ('review', 'order_only')
    THROW 51003, 'Ungueltige Rechnungsregel.', 1;

DECLARE @plan TABLE (
    shopify_id nvarchar(80) NOT NULL PRIMARY KEY,
    jtl_id int NOT NULL UNIQUE,
    current_payment_id int NOT NULL,
    row_version varchar(18) NOT NULL,
    match_names nvarchar(max) NOT NULL
);
INSERT INTO @plan
SELECT shopify_id, jtl_id, current_payment_id, row_version, match_names
FROM OPENJSON($1) WITH (
    shopify_id nvarchar(80), jtl_id int, current_payment_id int,
    row_version varchar(18), match_names nvarchar(max) AS JSON
);
DECLARE @expected int = (SELECT COUNT(*) FROM @plan);
IF @expected < 1 OR @maxChanges IS NULL OR @maxChanges < 1 OR @maxChanges > 100
   OR @expected > @maxChanges
    THROW 51004, 'Aenderungslimit verletzt. Keine Bestellung geaendert.', 1;
IF EXISTS (SELECT 1 FROM @plan WHERE current_payment_id = @target
           OR LEN(row_version) <> 18 OR LEFT(row_version, 2) <> '0x'
           OR TRY_CONVERT(binary(8), row_version, 1) IS NULL
           OR current_payment_id NOT IN (SELECT TRY_CONVERT(int, value) FROM OPENJSON($8)))
    THROW 51005, 'Ungueltiger Aenderungsplan oder unerlaubte Ausgangszahlungsart.', 1;

DECLARE @changed TABLE (jtl_id int PRIMARY KEY, old_payment_id int, new_payment_id int);
BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @lockResult int;
    EXEC @lockResult = sys.sp_getapplock
        @Resource = N'BB_KLARNA_AUFTRAGSZAHLUNGSART',
        @LockMode = 'Exclusive', @LockOwner = 'Transaction', @LockTimeout = 10000;
    IF @lockResult < 0 THROW 51006, 'Ein weiterer Klarna-Schreiblauf ist aktiv.', 1;

    IF NOT EXISTS (SELECT 1 FROM dbo.tZahlungsart WITH (UPDLOCK, HOLDLOCK)
                   WHERE kZahlungsart = @target AND nAktiv = 1)
        THROW 51007, 'Zielzahlungsart fehlt oder ist inaktiv.', 1;

    -- Do not silently choose one of multiple matching orders, even if a new match
    -- appeared between the SELECT and this transaction.
    IF EXISTS (
        SELECT 1 FROM @plan p WHERE
        (SELECT COUNT(*) FROM Verkauf.tAuftrag a WITH (UPDLOCK, HOLDLOCK)
         WHERE a.kShop = @shop AND a.nType = 1
           AND (a.cAuftragsNr IN (SELECT value FROM OPENJSON(p.match_names))
             OR a.cExterneAuftragsnummer IN (SELECT value FROM OPENJSON(p.match_names)))) <> 1
    ) THROW 51008, 'Auftragszuordnung ist nicht mehr eindeutig.', 1;

    IF EXISTS (
        SELECT 1 FROM @plan p
        LEFT JOIN Verkauf.tAuftrag a WITH (UPDLOCK, HOLDLOCK) ON a.kAuftrag = p.jtl_id
        WHERE a.kAuftrag IS NULL OR a.kShop IS NULL OR a.kShop <> @shop OR a.nType <> 1
           OR a.kZahlungsart IS NULL OR a.kZahlungsart <> p.current_payment_id
           OR a.bRowversion <> CONVERT(binary(8), p.row_version, 1)
           OR a.nStorno <> 0 OR a.nIstReadOnly <> 0 OR a.nPending <> 0
           OR a.nIstExterneRechnung <> 0
           OR NOT (a.cAuftragsNr IN (SELECT value FROM OPENJSON(p.match_names))
                OR ISNULL(a.cExterneAuftragsnummer, '') IN (SELECT value FROM OPENJSON(p.match_names)))
           OR EXISTS (SELECT 1 FROM Verkauf.tAuftragStorno s WITH (UPDLOCK, HOLDLOCK)
                      WHERE s.kAuftrag = a.kAuftrag)
           OR (@invoicePolicy = 'review' AND EXISTS (
               SELECT 1 FROM Rechnung.tRechnungPosition r WITH (UPDLOCK, HOLDLOCK)
               WHERE r.kAuftrag = a.kAuftrag))
    ) THROW 51009, 'JTL-Zustand hat sich geaendert oder der Auftrag ist gesperrt.', 1;

    UPDATE a
       SET kZahlungsart = @target
    OUTPUT inserted.kAuftrag, deleted.kZahlungsart, inserted.kZahlungsart INTO @changed
    FROM Verkauf.tAuftrag a
    JOIN @plan p ON p.jtl_id = a.kAuftrag
    WHERE a.kShop = @shop AND a.kZahlungsart = p.current_payment_id
      AND a.bRowversion = CONVERT(binary(8), p.row_version, 1);
    DECLARE @actual int = @@ROWCOUNT;
    IF @actual <> @expected THROW 51010, 'Unerwartete Anzahl geaenderter Auftraege.', 1;
    IF EXISTS (SELECT 1 FROM @plan p LEFT JOIN Verkauf.tAuftrag a ON a.kAuftrag = p.jtl_id
               WHERE a.kAuftrag IS NULL OR a.kZahlungsart IS NULL OR a.kZahlungsart <> @target)
        THROW 51011, 'Ruecklesen der Zahlungsart fehlgeschlagen.', 1;
    COMMIT TRANSACTION;
    SELECT p.shopify_id, c.jtl_id, c.old_payment_id, c.new_payment_id,
           CAST(1 AS bit) AS verified, SYSUTCDATETIME() AS changed_at_utc
    FROM @changed c JOIN @plan p ON p.jtl_id = c.jtl_id;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;

